INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('4bf9164a-ae65-41fb-95bc-0f16d486acbc', 'kanji', '会', '会', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kata radikal ketemu dan kanji ketemu itu sama!', 'Apa cara yang lebih baik untuk bertemu orang baru selain mulai bermain kayak (かい)! Naiklah ke kayakmu dan melayanglah ke dalam air. Pada akhirnya kamu akan bertemu orang lain yang sedang naik kayak dan boom, kamu bertemu orang baru!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
