INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('971e847f-cb01-45cf-b0a1-16b67338d6e5', 'kanji', '考', '考', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Di dalam peti mati ada seseorang yang mengemis. Tapi itu tidak akan berhasil. Anda tidak akan mendengarkan. Jadi, pria di dalam peti mati itu mulai berpikir: Apa yang bisa saya lakukan dengan lebih baik dalam hidup saya? Mengapa saya berada dalam situasi ini? Bagaimana saya bisa keluar? Pikirkan, sial, pikirkan!!', 'Apa yang dipikirkan pengemis itu? Gelembung pikiran muncul di dekat kepalanya. Di dalamnya ada gambar こういち! Dia berpikir jika こういち ada di sini, dia akan menyelamatkannya. Oh, andai saja こういち bisa menyelamatkan kita semua!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
