INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('d935e776-2ce1-41cd-b0e3-77f4e0b9693b', 'kanji', '安', '安', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Dengan atap di atas kepalanya, seorang wanita bisa bersantai. Dia tidak perlu khawatir tentang hujan atau salju atau mencari tempat yang aman untuk tidur. Atapnya juga sangat murah, sehingga dia bisa bersantai dengan keuangannya.', 'Saat dia bersantai, dia mengeluarkan makanan termurah dan paling menenangkan di dunia: ikan teri (あん).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
