INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('1b3eb9f0-3351-457f-9304-80123823e6e6', 'kanji', '肉', '肉', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Radikal daging dan daging memiliki tampilan dan makna yang sama.', 'Anda tahu ada makan orang di sini, dengan kanji ini. Jadi, ketika memikirkan daging ini, Anda harus memikirkan daging siapa itu. Dalam hal ini, itu adalah daging Nick (にく).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
