INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('5689130e-e5df-4dc4-8171-a4f85944d03e', 'kanji', '言', '言', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ucapan radikal dan ucapan kanji itu sama!', 'Jika Anda tidak yakin harus berkata apa, pikirkan saja tentang Genji (げん) dan tanyakan pada diri Anda, "Apa yang akan Genji katakan?"') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
