INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('ad8a055b-957d-43a1-ba74-6791c405ccb5', 'kanji', '作', '作', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kunci pemimpin adalah kunci yang membuat semua kunci lainnya. Ini seperti satu cincin untuk mengatur semuanya, satu cincin untuk mengikat mereka... kecuali dengan kunci.', 'Pemimpin membuat semua kunci dan memasukkannya ke dalam karung (さく) untuk dibagikan kepada bawahan, yang kemudian melihat (さ) bentuknya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
