INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('ccf3fa1d-701b-469a-b812-f45c21b4c9e0', 'kanji', '社', '社', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Tanamkan semangat sebelum Anda memulai perusahaan Anda dan itu akan sukses. Hal itulah yang dilakukan oleh perusahaan-perusahaan besar Jepang di masa lalu. Itu sebabnya perusahaan seperti Mitsubishi telah ada selama ratusan tahun. Mereka menanamkan semangat untuk membantu perusahaan mereka tumbuh, dan perusahaan itu pun berkembang!', 'Dari mana Anda belajar tentang metode pertumbuhan perusahaan ini? Dari dukun (しゃ), tentu saja. Dukun tidak hanya mengutarakan omong kosong, mereka tahu apa yang mereka bicarakan. Dan roh-roh ada di gang dukun mereka.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
