INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('2df7e287-2802-4a56-af0a-202b5a3673ff', 'kanji', '別', '別', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Di mulutmu kamu menaruh pedang dan pisau. Sekarang setelah Anda memilikinya di sana, Anda harus memisahkannya satu sama lain.', 'Mengapa kamu mencoba memisahkan pedang dan pisau di mulutmu? Karena seseorang bertaruh kamu (べつ) tidak bisa melakukannya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
