INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7e0227c6-891e-4e33-af87-cf37a362c437', 'vocabulary', '兄', '兄', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ngomong-ngomong, ini menyiratkan bahwa itu adalah kakak laki-lakimu. Bukan milik orang lain.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ngomong-ngomong, ini menyiratkan bahwa itu adalah kakak laki-lakimu. Bukan milik orang lain.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
