INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b84fc36-fe60-4d28-84c0-291ae0528a95', 'そのふくは古いので、もういりません。', 'Pakaian itu sudah tua, jadi saya tidak membutuhkannya lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b84fc36-fe60-4d28-84c0-291ae0528a95', '古いものにしがみついていては、あたらしいものをうけとることができません。', 'Jika Anda berpegang pada hal-hal lama, Anda tidak akan mendapatkan sesuatu yang baru.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b84fc36-fe60-4d28-84c0-291ae0528a95', 'ガレージで、古いパンツをみつけた。', 'Saya menemukan celana dalam tua di garasi kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('83e0e067-23de-41d0-ac0f-df089a7dd5ad', 'vocabulary', '中古', '中古', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kombinasi kanjinya kurang masuk akal, tapi tidak apa-apa. Ambil sesuatu yang berusia setengah baya dan Anda memiliki sesuatu yang bekas atau bekas. Belum 100% tua..masih di tengah-tengah, artinya kamu bisa memberikannya kepada orang lain untuk digunakan seperti adik-adikmu.', 'Kombinasi kanjinya kurang masuk akal, tapi tidak apa-apa. Ambil sesuatu yang berusia setengah baya dan Anda memiliki sesuatu yang bekas atau bekas. Belum 100% tua..masih di tengah-tengah, artinya kamu bisa memberikannya kepada orang lain untuk digunakan seperti adik-adikmu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
