INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0fd64212-b1f8-4426-b8b2-4cf00a40dca9', 'みょうじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0fd64212-b1f8-4426-b8b2-4cf00a40dca9', 'さくらさんの名字は何といいますか。', 'Siapa nama belakang Sakura?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0fd64212-b1f8-4426-b8b2-4cf00a40dca9', 'コウイチの名字をおしえてくれたら、お礼にてつ人二十八号のフィギュアをあげるよ。', 'Jika Anda memberi tahu saya nama belakang Koichi, saya akan memberi Anda sosok Tetsujin 28 sebagai imbalannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0fd64212-b1f8-4426-b8b2-4cf00a40dca9', '私の名字はあなたには絶対教えません。', 'Aku tidak akan pernah memberitahumu nama keluargaku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e6b494fb-ff53-4d12-8c8e-c3de096a17a4', 'vocabulary', '字', '字', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
