INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e6b494fb-ff53-4d12-8c8e-c3de096a17a4', 'もっとていねいに字をかいてください。', 'Harap menulis karakter dengan lebih hati-hati.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e6b494fb-ff53-4d12-8c8e-c3de096a17a4', '八の字まゆ毛の男せいとけっこんしました。', 'Saya menikah dengan seorang pria yang alisnya berbentuk seperti karakter angka delapan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e6b494fb-ff53-4d12-8c8e-c3de096a17a4', 'この字は何という意味ですか？', 'Apa arti karakter ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c70b0764-350b-4522-a615-efb481403211', 'vocabulary', '文字', '文字', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Menulis surat lebih sederhana dari kedengarannya. Ini benar-benar hanya sebuah surat, kan? Faktanya, Anda sedang membaca 文字 sekarang!', 'Menulis surat lebih sederhana dari kedengarannya. Ini benar-benar hanya sebuah surat, kan? Faktanya, Anda sedang membaca 文字 sekarang!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
