INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2ffbe878-636e-432c-a267-9712bcf184b8', 'さいしょの字は、大文字でかいてください。', 'Harap gunakan huruf kapital pada huruf pertama.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2ffbe878-636e-432c-a267-9712bcf184b8', 'タイトルを大文字でかき直してください。', 'Silakan tulis ulang judul dengan huruf besar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2ffbe878-636e-432c-a267-9712bcf184b8', '何故だかわからないけど、小文字より大文字の方が好きです。', 'Entah kenapa saya lebih suka huruf besar daripada huruf kecil.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c9f9aa7b-b281-434a-a61f-e97d6e4907f8', 'vocabulary', '去年', '去年', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Tahun lalu hanyalah tahun lalu.', 'Tahun lalu hanyalah tahun lalu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
