INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b36b063-116b-4e80-aeec-9f4dde0072ca', 'よていより、十五分早くつきました。', 'Kami tiba 15 menit lebih awal dari yang dijadwalkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b36b063-116b-4e80-aeec-9f4dde0072ca', 'かの女にこく白するのはまだ早いとおもうんだ。', 'Menurutku masih terlalu dini untuk mengajaknya kencan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b36b063-116b-4e80-aeec-9f4dde0072ca', '豆腐屋さんの朝はいつも早い。', 'Seorang pembuat tahu selalu bangun pagi-pagi sekali.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c0485a5f-8070-45b4-a032-33f3a00212be', 'vocabulary', '早々', '早々', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Intinya Anda memiliki kanji 早 dua kali, karena 々 hanyalah kanji pengulang. Ketika Anda memiliki sesuatu lebih awal dua kali, itu jelas memiliki semacam urgensi. Anda harus mengambil tindakan segera setelah Anda menyelesaikan apa pun yang Anda lakukan di sana.', 'Intinya Anda memiliki kanji 早 dua kali, karena 々 hanyalah kanji pengulang. Ketika Anda memiliki sesuatu lebih awal dua kali, itu jelas memiliki semacam urgensi. Anda harus mengambil tindakan segera setelah Anda menyelesaikan apa pun yang Anda lakukan di sana.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
