INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c0485a5f-8070-45b4-a032-33f3a00212be', '早々におへんじいただきありがとうございます。', 'Terima kasih atas balasan cepat Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c0485a5f-8070-45b4-a032-33f3a00212be', '年まつだからか、人々が早々とすぎさっていく。', 'Aku penasaran apakah ini karena ini akhir tahun, tapi orang-orang lewat dengan cepat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c0485a5f-8070-45b4-a032-33f3a00212be', '新年早々、借金を催促されるなんてひどすぎる。', 'Terlalu kejam meminta uang segera setelah awal tahun baru.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b8c04a52-effd-41cc-9b28-a517b84c8377', 'vocabulary', '足りる', '足りる', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti kaki atau cukup, dan kita akan menggunakan arti "cukup" untuk kata ini! Kata ini berarti cukup.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti kaki atau cukup, dan kita akan menggunakan arti "cukup" untuk kata ini! Kata ini berarti cukup.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
