INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da335c6e-ab2a-4bd8-9fe4-aaec4105a3bc', 'おつりが不足しています。', 'Saya tidak punya cukup uang kembalian.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da335c6e-ab2a-4bd8-9fe4-aaec4105a3bc', 'しきん不足で中央せいふのきかくしたプロジェクトが中止になった。', 'Karena kekurangan dana, proyek yang direncanakan pemerintah pusat terhenti.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da335c6e-ab2a-4bd8-9fe4-aaec4105a3bc', '経験が不足しているうえにいつも寝不足なので、あなたは首です。', 'Anda dipecat karena kurang pengalaman dan selalu kurang tidur.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('df567719-f097-4384-b5ed-335766fec971', 'vocabulary', '写す', '写す', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menyalin jadi kalian pasti tahu ini artinya menyalin. Anda tahu kata ini berarti "menyalin" karena diakhiri dengan す. Anda menyalin dokumen yang Anda perlukan untuk menuntut (す) seseorang yang telah menipu Anda.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menyalin jadi kalian pasti tahu ini artinya menyalin. Anda tahu kata ini berarti "menyalin" karena diakhiri dengan す. Anda menyalin dokumen yang Anda perlukan untuk menuntut (す) seseorang yang telah menipu Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
