INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df567719-f097-4384-b5ed-335766fec971', 'となりのページに、この字を写してください。', 'Silakan salin karakter ke halaman berikutnya buku kerja Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df567719-f097-4384-b5ed-335766fec971', 'ビエトの写す写しんの大ファンです。', 'Saya penggemar berat foto yang diambil Viet.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df567719-f097-4384-b5ed-335766fec971', 'お経を書き写すには、千円支払う必要があります。', 'Anda harus membayar 1.000 yen untuk menyalin sutra dengan tangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6d2b7ac0-e461-4fc0-bd1a-d635e5e87542', 'vocabulary', '写る', '写る', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya salinan, tapi apa itu salinan? Pada dasarnya ini adalah sebuah foto, itulah sebabnya kata ini berarti difoto, atau berada di dalam sebuah foto. Anda tahu yang ini "untuk difoto" karena diakhiri dengan る. Seseorang menganggap Anda "kasar" sehingga mereka memotret Anda.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya salinan, tapi apa itu salinan? Pada dasarnya ini adalah sebuah foto, itulah sebabnya kata ini berarti difoto, atau berada di dalam sebuah foto. Anda tahu yang ini "untuk difoto" karena diakhiri dengan る. Seseorang menganggap Anda "kasar" sehingga mereka memotret Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
