INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7aaab382-385b-4859-a8e7-f4eb67b20436', '日よう日に会う。', 'Kami bertemu pada hari Minggu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7aaab382-385b-4859-a8e7-f4eb67b20436', 'ポートランドくうこうでばったりコウイチに会いました。', 'Saya bertemu Koichi di bandara Portland.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7aaab382-385b-4859-a8e7-f4eb67b20436', '明日の午後、大好きな俳優に会えるんです！', 'Saya bisa bertemu aktor favorit saya besok sore.') ON CONFLICT DO NOTHING;
