INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bb0115d2-fa71-4861-a6ea-2f15e828ab06', 'それらは、同日にはつばいされました。', 'Itu diluncurkan pada hari yang sama.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bb0115d2-fa71-4861-a6ea-2f15e828ab06', 'すきなバンドのライブがちがうはこで同日にかぶっていて、どれにいこうかちょうぜつまよっています。', 'Band yang saya suka mengadakan konser di klub musik yang berbeda pada hari yang sama dan saya benar-benar tidak yakin harus datang ke klub mana.') ON CONFLICT DO NOTHING;